<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import UiIcon from './UiIcon.vue'
import { useSession, type Config } from './api'
import { clone } from './editor'
const api=useSession().request
interface KeyFile {path:string; publicPath:string; privateFile:boolean; publicFile:boolean; publicKey:string|null; fingerprint:string|null; error:string|null}
interface Inventory {agentStatus:{available:boolean;socket:string|null;candidates:string[];reason?:string};files:KeyFile[]; agent:string|null; agentError:string|null}
const props=defineProps<{config:Config;revision:string}>()
const emit=defineEmits<{refresh:[];notice:[message:string]}>()
const inventory=ref<Inventory|null>(null),pending=ref(''),error=ref(''),path=ref(''),search=ref(''),comments=ref<Record<string,string>>({}),socket=ref('')
const filename=(p:string)=>p.split(/[\\/]/).at(-1)||p
const identity=(key:string)=>key.trim().split(/\s+/).slice(0,2).join(' ')
const agentKeys=computed(()=>inventory.value?.agent?.trim().split('\n').filter(Boolean).map(publicKey=>{const [algorithm,,...comment]=publicKey.trim().split(/\s+/);return {publicKey,algorithm,comment:comment.join(' '),registered:inventory.value!.files.some(k=>k.publicKey&&identity(k.publicKey)===identity(publicKey))}})||[])
const files=computed(()=>(inventory.value?.files||props.config.keyFiles.map(path=>({path,publicPath:'',privateFile:false,publicFile:false,publicKey:null,fingerprint:null,error:null}))).filter(k=>`${k.path} ${k.fingerprint}`.toLowerCase().includes(search.value.toLowerCase())))
const loaded=(k:KeyFile)=>!!k.publicKey&&agentKeys.value.some(a=>identity(a.publicKey)===identity(k.publicKey!))
async function load(){inventory.value=await api<Inventory>('keys.list')}
async function run(id:string,fn:()=>Promise<void>){if(pending.value)return;pending.value=id;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{pending.value='';emit('refresh')}}
async function register(generate=false){await run('register',async()=>{const p=path.value.trim();if(!p)throw Error('请输入密钥文件的绝对路径');if(generate&&p.endsWith('.pub'))throw Error('生成密钥时请输入私钥的保存路径');if(!props.config.keyFiles.includes(p)){const c=clone(props.config);c.keyFiles.push(p);await api('save',{config:c,revision:props.revision})}if(generate)await api('keys.generate',{path:p,algorithm:'ed25519'});path.value='';await load();emit('notice',generate?'密钥已生成':'密钥路径已登记')})}
async function operate(action:string,k:KeyFile){await run(k.path,async()=>{if(action==='keys.public'){const r=await api<{publicKey:string}>(action,{path:k.path});await navigator.clipboard.writeText(r.publicKey)}else await api(action,{path:k.path,...(action==='keys.comment'?{comment:comments.value[k.path]||''}:{})});await load();emit('notice',({'keys.public':'公钥已复制','agent.add':'已加载 Agent','agent.remove':'已移出 Agent','keys.passphrase':'密钥口令已修改','keys.comment':'公钥备注已保存'} as Record<string,string>)[action]!)})}
onMounted(()=>run('refresh',load))
</script>
<template>
 <div class="toolbar"><span class="search-field grow"><UiIcon name="search" :size="16" /><input v-model="search" aria-label="搜索密钥" placeholder="搜索文件名、路径或指纹"></span><span class="toolbar-spacer"></span><button class="icon-button" title="刷新密钥与 Agent" aria-label="刷新密钥与 Agent" :disabled="!!pending" @click="run('refresh',load)"><UiIcon name="refresh" /><span class="sr-only">刷新密钥与 Agent</span></button></div>
 <p v-if="error" class="message error" role="alert"><UiIcon name="alert" :size="15" /><span>{{error}}</span><button class="icon-button" title="关闭" aria-label="关闭" @click="error=''"><UiIcon name="close" :size="15" /><span class="sr-only">关闭</span></button></p>
 <section v-if="inventory?.agentStatus&&!inventory.agentStatus.available" class="panel agent-setup"><div class="panel-heading"><div><span class="eyebrow">没有可用的 Agent</span><h2>连接已有 Agent</h2></div><UiIcon name="key" :size="20" /></div><p class="muted">{{inventory.agentStatus.reason}}</p><label>Agent socket 路径<input v-model="socket" list="agent-sockets" placeholder="/tmp/ssh-…/agent.…"><datalist id="agent-sockets"><option v-for="p in inventory.agentStatus.candidates" :key="p" :value="p" /></datalist></label><button :disabled="!!pending||!socket" @click="run('agent-bind',async()=>{await api('agent.bind',{path:socket});await load()})">绑定 socket</button></section>
 <form class="panel key-register" @submit.prevent="register()"><div class="register-heading"><span class="badge">登记密钥</span><small>已有文件或新路径</small></div><label>密钥文件的绝对路径<input v-model="path" required placeholder="C:/Users/you/.ssh/id_ed25519"></label><div class="actions"><button class="primary" :disabled="!!pending"><UiIcon name="plus" :size="16" /><span>登记路径</span></button><button type="button" title="在新路径生成 Ed25519 密钥" aria-label="在新路径生成 Ed25519 密钥" :disabled="!!pending||!path.trim()" @click="register(true)"><UiIcon name="zap" :size="16" /><span>生成密钥</span></button></div></form>
 <section class="key-list" aria-labelledby="key-list-title" :aria-busy="pending==='refresh'"><div class="key-section-heading"><h2 id="key-list-title">已登记密钥 <span class="count">{{config.keyFiles.length}}</span></h2><span class="section-note">私钥只读</span></div>
  <p v-if="!inventory&&pending==='refresh'" class="empty compact" role="status">正在读取密钥…</p><p v-else-if="!config.keyFiles.length" class="empty compact">还没有登记密钥，在上方填写已有文件路径或生成新密钥。</p><p v-else-if="!files.length" class="empty compact">没有匹配的密钥。<button class="text-button" @click="search=''">清除搜索</button></p>
  <article v-for="k in files" :key="k.path" class="key-row" :aria-label="filename(k.path)">
   <div class="key-summary"><div class="key-title"><span class="key-mark"><UiIcon name="file" :size="16" /></span><h3>{{filename(k.path)}}</h3><span class="key-kind">{{!inventory?'待检查':k.privateFile?(k.publicFile?'私钥 + 公钥':'私钥 · 公钥缺失'):k.publicFile?'仅公钥':'文件缺失'}}</span><span v-if="loaded(k)" class="status running">已加载 Agent</span></div><code class="key-path">{{k.path}}</code><p v-if="k.fingerprint" class="key-fingerprint">{{k.fingerprint.trim()}}</p><p v-if="k.error" class="error inline" role="alert">{{k.error||'无法读取密钥指纹'}}</p></div>
   <div class="actions key-actions"><button class="icon-button" title="复制公钥" aria-label="复制公钥" :disabled="!!pending||!k.publicFile" @click="operate('keys.public',k)"><UiIcon name="copy" /><span class="sr-only">复制公钥</span></button><button v-if="!loaded(k)" class="icon-button" title="加载 Agent" aria-label="加载 Agent" :disabled="!!pending||!k.privateFile" @click="operate('agent.add',k)"><UiIcon name="key" /><span class="sr-only">加载 Agent</span></button><button v-else class="icon-button" title="移出 Agent" aria-label="移出 Agent" :disabled="!!pending" @click="operate('agent.remove',k)"><UiIcon name="check" /><span class="sr-only">移出 Agent</span></button><details class="row-menu"><summary title="更多密钥操作" aria-label="更多密钥操作"><UiIcon name="more" /><span class="sr-only">更多</span></summary><div class="menu-panel"><button :disabled="!!pending||!k.privateFile" @click="operate('keys.passphrase',k)"><UiIcon name="key" :size="16" /><span>修改口令</span></button><form v-if="k.privateFile" @submit.prevent="operate('keys.comment',k)"><label>公钥备注<input v-model="comments[k.path]" placeholder="输入新的公钥备注"></label><button :disabled="!!pending||comments[k.path]===undefined">保存备注</button></form><details v-if="k.publicKey" class="menu-public-key"><summary><UiIcon name="key" :size="14" /><span>查看公钥</span><UiIcon name="chevron-down" :size="13" class="summary-chevron" /></summary><pre>{{k.publicKey}}</pre></details></div></details></div>
   <p v-if="pending===k.path" class="muted key-pending" role="status">正在处理，请按提示完成认证…</p>
  </article>
 </section>
 <section class="panel agent-panel" aria-labelledby="agent-title"><div class="key-section-heading"><h2 id="agent-title">SSH Agent <span class="count">{{agentKeys.length}} 个身份</span></h2><span class="status" :class="inventory?.agentError?'failed':'running'">{{inventory?.agentError?'不可用':'已连接'}}</span></div><p v-if="inventory?.agentError" class="muted break" role="status">{{inventory.agentError||'Agent 未运行或没有加载身份'}}</p><p v-else-if="inventory&&!agentKeys.length" class="muted">Agent 中暂无身份。</p><article v-for="a in agentKeys" :key="identity(a.publicKey)" class="agent-row"><div class="key-title"><span class="key-mark"><UiIcon name="key" :size="15" /></span><strong>{{a.comment||'未命名身份'}}</strong><span class="key-kind">{{a.algorithm}}</span><span class="muted">{{a.registered?'已登记文件':'仅 Agent 身份'}}</span></div><details><summary><UiIcon name="key" :size="14" /><span>查看公钥</span><UiIcon name="chevron-down" :size="13" class="summary-chevron" /></summary><pre>{{a.publicKey}}</pre></details></article></section>
</template>
